// lib/collection/src/shards/local_shard/shard_ops.rs line 50-97
async fn update(
    &self,
    mut operation: OperationWithClockTag,
    wait: bool,
) -> CollectionResult<UpdateResult> {
    let (callback_sender, callback_receiver) = if wait {
        let (tx, rx) = oneshot::channel();
        (Some(tx), Some(rx))  // wait=true: creates callback for validation errors
    } else {
        (None, None)  // wait=false: no callback, errors lost
    };

    // ... operation queued ...

    if let Some(receiver) = callback_receiver {
        let _res = receiver.await??;  // wait=true: awaits validation result
        Ok(UpdateResult {
            operation_id: Some(operation_id),
            status: UpdateStatus::Completed,
            clock_tag: operation.clock_tag,
        })
    } else {
        Ok(UpdateResult {
            operation_id: Some(operation_id),
            status: UpdateStatus::Acknowledged,  // wait=false: returns immediately
            clock_tag: operation.clock_tag,
        })
    }
}

